// What Claude Code passes a ui.render hook for this pane.
const PANE = {
  plugin: 'brain-memory',
  component: 'Pane',
  requestId: 'brain-memory',
  surface: 'terminal',
  viewport: { columns: 120, rows: 40 },
  props: {
    title: 'Brain memory',
    isFocused: true,
    bodyColumns: 60,
    placement: 'inline',
    scroll: { offset: 0, bodyRows: 20 },
    view: {},
  },
} as const

