content.content:
// brain-memory — show what Entire Brain actually contributed to each turn.
//
// Brain's value is invisible today. Facts get retrieved, the agent uses them or
// does not, and nobody sees either. The expensive case is the EMPTY answer: an
// empty result that nobody notices is how a brain quietly stops being consulted
// while everyone still believes it is working.
//
// So this mod records every brain call, groups them by turn, and puts the empty
// ones in front of you -- with brain's own blind_spot note, which says WHY it
// had nothing and is otherwise buried in a JSON payload no human reads.

import { atom, read, update } from 'claude-code'

const PANE = 'brain-memory'
const MAX_TURNS = 10
const MAX_ENTRIES = 200

// These live in $.state, not in module variables, because `register` runs again
// on every reload and module variables start over. A pane that forgets every
// call each time the file is saved is useless during exactly the work it is
// meant to support -- and worse, its empty state then looks like "brain was
// never called", the false negative this mod exists to prevent.
//
// $.state also redraws its readers on write, so no $.ui.invalidate is needed.
const calls = atom({ plugin: 'brain-memory', key: 'calls' }, [])
const turnNo = atom({ plugin: 'brain-memory', key: 'turn' }, 0)

// Not state: this only caps transcript noise, and starting over on reload is
// harmless. Keeping it out of the contract keeps the contract about the pane.
let logged = 0

// --- recognising a brain call ------------------------------------------------
// Brain is reached two ways and both count: the MCP tools an agent calls
// directly, and the CLI run through Bash. A mod that watched only one would
// report "brain was never called" for half the sessions that did call it.

const MCP_PREFIX = 'mcp__entire-brain__'
const CLI_VERB = /\b(?:entire\s+brain|entire-brain)\s+([a-z][a-z-]*)/

function brainCallOf(e) {
  const tool = String(e?.tool ?? '')
  if (tool.startsWith(MCP_PREFIX)) {
    const verb = tool.slice(MCP_PREFIX.length).replace(/^brain_/, '')
    return { verb, via: 'mcp', query: queryOf(e) }
  }

