cd /Users/suhaan/devenv/.claude/mods/brain-memory
python3 - <<'PY'
p='hooks/register.js'; s=open(p).read()

# 1. the usage atom, beside the others
anchor = "const turnNo = atom({ plugin: 'brain-memory', key: 'turn' }, 0)\n"
assert anchor in s
s = s.replace(anchor, anchor + "// The collected usage window. Null until /brainusage has run once: an empty\n// object would render as \"brain was never used\", the false negative again.\nconst usage = atom({ plugin: 'brain-memory', key: 'usage' }, null)\n")

# 2. the rendering helpers, before register()
helpers = r'''
// --- /brainusage: how the agent has been using brain over time ---------------
// The per-turn pane answers "what did brain give me just now". It cannot answer
// "is the agent reaching for brain at all, and is it getting anything back",
// because $.state resets on /clear and /resume. That question needs history, and
// the only record of it is the transcript corpus -- so a collector script reads
// it and this pane draws the result.

const USAGE_PANE = 'brain-usage'
const DEFAULT_DAYS = 31
const COLLECTOR = '/scripts/collect-usage.py'

// Cool -> warm as usage rises. Reaching for brain is the GOOD case, so the ramp
// runs quiet-to-hot. A day with nothing is dim, never coloured: a zero that is
// given a colour reads as a value, which is the mistake this whole mod is about.
const RAMP = ['blue', 'cyan', 'green', 'yellow', 'red']
const BARS = ['▁', '▂', '▃', '▅', '▆', '▇', '█']
const CELL = '██'
const EMPTY_CELL = '··'

function bucket(n, max) {
  if (!n) return -1
  if (max <= 0) return 0
  return Math.min(RAMP.length - 1, Math.max(0, Math.ceil((n / max) * RAMP.length) - 1))
}

function barGlyph(n, max) {
  if (!n) return '·'
  if (max <= 0) return BARS[0]
  return BARS[Math.min(BARS.length - 1, Math.max(0, Math.ceil((n / max) * BARS.length) - 1))]
}

// The collector reports only days that HAVE events. The chart needs every day in
// the window, zeros included -- a chart that silently omits quiet days makes a
// gap look like continuous use.
function windowDays(data) {
  const out = []
  const start = Date.parse((data?.window_start || '') + 'T00:00:00Z')
  const span = Number(data?.window_days) || DEFAULT_DAYS
  if (!Number.isFinite(start)) return out
  for (let i = 0; i < span; i += 1) {
    const date = new Date(start + i * 86400000)
    const key = date.toISOString().slice(0, 10)
    const row = data?.days?.[key] || null
    out.push({
      key,
      date,
      total: row ? (row.mcp || 0) + (row.bash || 0) : 0,
      mcp: row ? row.mcp || 0 : 0,
      bash: row ? row.bash || 0 : 0,
      answered: row ? row.answered || 0 : 0,
      empty: row ? row.empty || 0 : 0,
      failed: row ? row.failed || 0 : 0,
      tools: row ? row.tools || {} : {},
    })
  }
  return out
}

// Monday-first columns, one column per calendar week, so the shape matches the
// week a person actually worked rather than an arbitrary 7-day chop.
function weeksOf(days) {
  const weeks = []
  let col = null
  for (const d of days) {
    const dow = (d.date.getUTCDay() + 6) % 7
    if (col === null || dow === 0) {
      col = new Array(7).fill(null)
      weeks.push(col)
    }
    col[dow] = d
  }
  return weeks
}

function totals(days) {
  const t = { calls: 0, answered: 0, empty: 0, failed: 0, mcp: 0, bash: 0, active: 0, tools: {} }
  for (const d of days) {
    t.calls += d.total
    t.answered += d.answered
    t.empty += d.empty
    t.failed += d.failed
    t.mcp += d.mcp
    t.bash += d.bash
    if (d.total > 0) t.active += 1
    for (const [verb, n] of Object.entries(d.tools)) t.tools[verb] = (t.tools[verb] || 0) + n
  }
  return t
}

'''
anchor2 = 'export function register(on) {'
assert anchor2 in s
s = s.replace(anchor2, helpers + anchor2)
open(p,'w').write(s)
print('helpers inserted')
PY
node --input-type=module -e "import('./hooks/register.js').then(()=>console.log('module parses')).catch(e=>{console.error('PARSE FAIL',e.message);process.exit(1)})" 2>&1 | tail -3

