    await $.ui.open({ id: PANE, title: 'Brain memory', focus: true, closeOnEscape: true })
    return {}
  })"""
new2 = old2 + """

  on('command.run', { command: 'brainusage' }, async ($, e) => {
    // `/brainusage 7` narrows the window; a month is the default because the
    // question is "is this habit forming", and a week is too short to answer it.
    const raw = String(e?.args ?? e?.argv?.join(' ') ?? '').match(/\\d+/)
    const days = Math.min(366, Math.max(1, raw ? Number(raw[0]) : DEFAULT_DAYS))

    await update($, usage, (prev) => ({ ...(prev || {}), loading: true, days }))
    let next_
    try {
      // The corpus is gigabytes, so the scan happens in a child process, once,
      // here -- not in the render hook, which runs on every redraw.
      const { exitCode, stdout, stderr } = await $.process.run(
        ['python3', $.plugin.root + COLLECTOR, String(days)],
        { timeoutMs: 120000 },
      )
      next_ = exitCode === 0
        ? { loading: false, days, data: JSON.parse(stdout), error: '' }
        : { loading: false, days, data: null, error: (stderr || 'collector exited ' + exitCode).trim().slice(0, 400) }
    } catch (err) {
      next_ = { loading: false, days, data: null, error: String(err?.message || err).slice(0, 400) }
    }
    await update($, usage, () => next_)
    await $.ui.open({ id: USAGE_PANE, title: 'Brain usage', focus: true, closeOnEscape: true })
    return {}
  })"""
