test('/brain-memory opens the pane', async ($, on) => {
  const opened: unknown[] = []
  on('command.register', () => ({ value: undefined }))
  on('ui.log', () => ({ value: undefined }))
  on('ui.render', () => ({ type: 'Text', props: {}, children: ['drawn by Claude Code'] }))
  on('tool.call', () => ({ result: '' }))
  on('ui.open', ($, e) => {
    opened.push(e)
    return { value: { isPlaced: true } }
  })

  const answer = await $.command.run({ command: 'brain-memory', args: '' })
  expect(answer).toEqual({})
  expect(opened).toMatchObject([{ id: 'brain-memory', title: 'Brain memory' }])
})

// Brain payloads are large -- one real `query` here is 39 KB over 103 lines --
// and Claude Code truncates long Bash output, so the JSON a hook receives often
