// --- /brainusage -------------------------------------------------------------
// The per-turn pane cannot answer "is the agent reaching for brain at all", because
// $.state resets on /clear and /resume. /brainusage answers it from the transcript
// corpus, which means a child process -- so these guards pin the contract with it.

const USAGE_PANE = { ...PANE, requestId: 'brain-usage', props: { ...PANE.props, title: 'Brain usage' } } as const

