    window_days: 7,
    window_start: '2026-10-05',
    files_scanned: 1326,
    events: 0,
    days,
    ...extra,
  })

function usageHarness(on, run: (e) => unknown) {
  on('command.register', () => ({ value: undefined }))
  on('ui.log', () => ({ value: undefined }))
  on('ui.render', () => ({ type: 'Text', props: {}, children: ['drawn by Claude Code'] }))
  on('ui.open', () => ({ value: { isPlaced: true } }))
  on('process.run', ($, e) => ({ value: run(e) }))
}

test('/brainusage runs the collector and draws the window', async ($, on) => {
  usageHarness(on, () => ({
    exitCode: 0,
    stdout: usageJson({
      '2026-10-09': { mcp: 1, bash: 9, answered: 8, empty: 2, failed: 0, tools: { query: 6, recall: 4 } },
      '2026-10-11': { mcp: 0, bash: 4, answered: 4, empty: 0, failed: 0, tools: { brief: 4 } },
    }),
    stderr: '',
    isStdoutTruncated: false,
    isStderrTruncated: false,
  }))

  await $.command.run({ command: 'brainusage', args: '7' })
  const ui = await $.ui.mount(USAGE_PANE)

  expect(await ui.find({ type: 'Text', text: '14 calls' })).toBeDefined()
  expect(await ui.find({ type: 'Text', text: '12 answered' })).toBeDefined()
  // The empty rate is the signal worth surfacing, not a footnote.
  expect(await ui.find({ type: 'Text', text: '2 empty (14%)' })).toBeDefined()
  // Two of seven days had traffic: the quiet five must still be counted.
  expect(await ui.find({ type: 'Text', text: '2 of 7 days active' })).toBeDefined()
})

test('the window argument reaches the collector', async ($, on) => {
  const argv: unknown[] = []
  usageHarness(on, (e) => {
    argv.push(e.argv ?? e.command ?? e)
    return { exitCode: 0, stdout: usageJson({}), stderr: '', isStdoutTruncated: false, isStderrTruncated: false }
  })

  await $.command.run({ command: 'brainusage', args: '7' })
  // Without this the pane would silently draw a month whatever was asked for.
  expect(JSON.stringify(argv)).toContain('7')
  expect(JSON.stringify(argv)).toContain('collect-usage.py')
})

test('a collector that fails says so, and names the command to run by hand', async ($, on) => {
  usageHarness(on, () => ({
    exitCode: 2,
    stdout: '',
    stderr: 'Traceback: no such file',
    isStdoutTruncated: false,
    isStderrTruncated: false,
  }))

  await $.command.run({ command: 'brainusage', args: '' })
  const ui = await $.ui.mount(USAGE_PANE)
  // A pane that goes blank on failure is indistinguishable from "no usage",
  // which is the exact false negative this mod exists to prevent.
  expect(await ui.find({ type: 'Text', text: 'Traceback: no such file' })).toBeDefined()
  expect(await ui.find({ type: 'Text', text: /collect-usage\.py/ })).toBeDefined()
})

test('a genuinely quiet month says so without claiming brain was never called', async ($, on) => {
  usageHarness(on, () => ({
    exitCode: 0,
