# keep only the verb; the spelling is decided where it is printed, because the
# dispatch form depends on the reader's install and a package-level var would
# freeze whatever the environment said at init.
def strip(m):
    return '%s"%s"' % (m.group(1), m.group(2))
new_table, n = re.subn(r'(:\s*)"entire brain ([a-z][a-z\- ]*)"', strip, table)
assert n >= 15, f'expected >=15 rewrites, got {n}'
