// mergeUnknownManifestFields is tested directly here because the caller cannot
// reach this case: unknownManifestFields filters declared keys out, so the
// guard inside the merge is defensive. Defensive is not the same as untested --
// a later caller passing an unfiltered map would silently resurrect stale
// values over freshly computed ones, and nothing above would notice.
func TestTheMergeRefusesToOverwriteADeclaredKey(t *testing.T) {
	t.Parallel()
	encoded, err := json.MarshalIndent(map[string]any{
		"repo_key":     "local/fresh",
		"retired_only": "keep me",
	}, "", "  ")
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}

	merged, err := mergeUnknownManifestFields(encoded, map[string]json.RawMessage{
		"repo_key":     json.RawMessage(`"local/STALE"`), // declared: must lose
		"carried_over": json.RawMessage(`"keep me too"`), // unmodelled: must win
	})
	if err != nil {
		t.Fatalf("merge: %v", err)
	}

	var out map[string]json.RawMessage
	if err := json.Unmarshal(merged, &out); err != nil {
		t.Fatalf("merged output is not valid JSON: %v", err)
	}
	var key string
	if err := json.Unmarshal(out["repo_key"], &key); err != nil {
		t.Fatalf("repo_key unreadable: %v", err)
	}
	if key != "local/fresh" {
		t.Fatalf("a preserved value overwrote a freshly computed one: %q", key)
	}
	if _, ok := out["carried_over"]; !ok {
		t.Fatal("an unmodelled key was not carried through")
	}
	if _, ok := out["retired_only"]; !ok {
		t.Fatal("the merge dropped a key that was already in the encoded bytes")
	}
}
