func TestTheImportIsRecordedBeforeAnythingIsReplaced(t *testing.T) {
	t.Parallel()
	src := readFileString(t, "semantic.go")

	fn := src[strings.Index(src, "func runSemanticBundleImport("):]
	fn = fn[:strings.Index(fn, "\n}\n")]
	if fn == "" {
