	}
	if audit > walk {
		t.Fatal("the import is recorded AFTER layers are replaced: a failed audit write destroys the facts and leaves no trace of why")
	}
	if strings.Count(fn, `appendSemanticAudit(storage.BrainDir, "bundle_import"`) != 1 {
