// --claude-hook used to bypass the terminal-stdin guard, so hand-running the
// exact command the docs suggest blocked for ever on a read that never returns,
// while the comment two lines above claimed a terminal stdin is never read.
// Raised as a finding on this PR, and correct.
//
// A terminal is simulated with a non-pipe reader: stdinIsPipe is what the
// production path consults, so this exercises the same branch.
func TestClaudeHookOnATerminalSaysSoInsteadOfHanging(t *testing.T) {
	t.Parallel()
	cmd := newHookCommand(Options{Env: EntireEnv{}, Now: time.Now})
	cmd.SetArgs([]string{"pre-edit", "--claude-hook"})
	cmd.SetIn(notAPipe{})
	var out, errOut bytes.Buffer
	cmd.SetOut(&out)
	cmd.SetErr(&errOut)

	err := cmd.Execute()
	if err == nil {
		t.Fatal("a terminal stdin must be refused, not read: this is the hand-run that used to hang")
	}
	for _, want := range []string{"stdin is a terminal", "--file"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("the refusal must say what to do instead; missing %q in: %v", want, err)
		}
	}
}

// notAPipe stands in for an interactive terminal: stdinIsPipe only treats an
// *os.File whose mode says FIFO as a pipe, so any other reader is "a terminal"
// for the purposes of this branch.
type notAPipe struct{}

func (notAPipe) Read([]byte) (int, error) { return 0, io.EOF }
GO
