func stdinIsPipe(r io.Reader) bool {
	file, ok := r.(*os.File)
	if !ok {
		// A test buffer or any other reader: readable without blocking.
		return true
	}
	info, err := file.Stat()
	if err != nil {
		return false
	}
	return info.Mode()&os.ModeCharDevice == 0
}

