package main

import (
	"fmt"
	"strings"
)

// winDir mimics what filepath.Dir does on Windows: Clean() rewrites every
// forward slash to the OS separator, so the result is backslash-separated.
func winDir(p string) string {
	p = strings.ReplaceAll(p, "/", `\`)
	if i := strings.LastIndex(p, `\`); i > 0 {
		return p[:i]
	}
	return p
}

func quote(s string) string { return "'" + s + "'" }

func main() {
	path := winDir("/var/root/entire/plugins/data" + "/x") // the Path as Clean'd
	remedy := "chmod u+w " + quote(winDir(path))

	oldWant := quote("/var/root/entire/plugins") // hard-coded forward slashes
	newWant := quote(winDir(path))               // derived the same way

	fmt.Printf("remedy      = %s\n", remedy)
	fmt.Printf("old assert  -> contains(%s) = %v\n", oldWant, strings.Contains(remedy, oldWant))
	fmt.Printf("new assert  -> contains(%s) = %v\n", newWant, strings.Contains(remedy, newWant))
}
EOF
go run main.go

