	write := func(dir, line string) {
		if err := os.MkdirAll(filepath.Join(dir, semanticDirName), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(dir, semanticDirName, semanticAuditLogName), []byte(line+"\n"), 0o600); err != nil {
			t.Fatal(err)
		}
	}

