package cli

import (
	"bytes"
	"errors"
	"strings"
	"testing"

	"github.com/entireio/entire-brain/internal/tui"
)

// The three hooks below exist for a caller that composes its own settled rows
// (internal/setupui). Each guards the one property that made the hook
// necessary; see progress.go for why Note/Finish could not serve.

func TestProgressTTYReportsTheRendererCapability(t *testing.T) {
	t.Parallel()
	var buf bytes.Buffer
	plain := newProgressWithRenderer(&buf, "", tui.NewRenderer(tui.PlainCaps()))
	if plain.TTY() {
		t.Fatal("a plain renderer must not report TTY")
	}
	term := newProgressWithRenderer(&buf, "", tui.NewRenderer(tui.Caps{TTY: true}))
	if !term.TTY() {
		t.Fatal("a TTY renderer must report TTY")
	}
}

func TestEmitLineWritesTheLineVerbatim(t *testing.T) {
	t.Parallel()
	var buf bytes.Buffer
	p := newProgressWithRenderer(&buf, "", tui.NewRenderer(tui.PlainCaps()))
	const line = "+ Build     instant core ready -- 9 components"
	p.EmitLine(line)

	got := buf.String()
	if got != line+"\n" {
		t.Fatalf("EmitLine must write the line verbatim.\n got: %q\nwant: %q", got, line+"\n")
	}
	// The distinction from NotePhase, which is why this hook exists at all.
	if strings.HasPrefix(got, "  ") {
		t.Fatalf("EmitLine must not indent like NotePhase: %q", got)
	}
}

func TestEmitLineDiffersFromNotePhase(t *testing.T) {
	t.Parallel()
	const line = "watcher  not installed"
	var emitted, noted bytes.Buffer
	newProgressWithRenderer(&emitted, "", tui.NewRenderer(tui.PlainCaps())).EmitLine(line)
	newProgressWithRenderer(&noted, "", tui.NewRenderer(tui.PlainCaps())).NotePhase(line, tui.PhaseNeutral)
	if emitted.String() == noted.String() {
		t.Fatalf("EmitLine and NotePhase must differ, else the hook is unnecessary; both produced %q", emitted.String())
	}
}

func TestAbandonWritesNothing(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		name string
		caps tui.Caps
	}{
		{"plain", tui.PlainCaps()},
		{"tty", tui.Caps{TTY: true, Width: 80}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			var buf bytes.Buffer
			p := newProgressWithRenderer(&buf, "", tui.NewRenderer(tc.caps))
			task := p.Begin("fact backfill")
			task.Abandon()
			if out := stripANSIForTest(buf.String()); strings.TrimSpace(out) != "" {
				t.Fatalf("Abandon must write nothing, got %q", out)
			}
		})
	}
}

func TestAbandonThenFinishStillWritesOneLineAtMost(t *testing.T) {
	t.Parallel()
	var buf bytes.Buffer
	p := newProgressWithRenderer(&buf, "", tui.NewRenderer(tui.PlainCaps()))
	task := p.Begin("fact backfill")
	task.Abandon()
	task.Finish(errors.New("boom")) // a second terminal line is the bug Finish's flag prevents
	if out := stripANSIForTest(buf.String()); strings.TrimSpace(out) != "" {
		t.Fatalf("Finish after Abandon must stay silent, got %q", out)
	}
}

func TestFinishStillWritesWhenNotAbandoned(t *testing.T) {
	t.Parallel()
	// Non-vacuity for the two tests above: the same setup DOES write when the
	// task is finished normally, so their silence is Abandon's doing.
	var buf bytes.Buffer
	p := newProgressWithRenderer(&buf, "", tui.NewRenderer(tui.PlainCaps()))
	task := p.Begin("fact backfill")
	task.Finish(nil)
	if strings.TrimSpace(buf.String()) == "" {
		t.Fatal("a normally finished task must still write its line")
	}
}

func stripANSIForTest(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); {
		if s[i] == 0x1b {
			for i < len(s) && !(s[i] >= 'a' && s[i] <= 'z') && !(s[i] >= 'A' && s[i] <= 'Z') {
				i++
			}
			if i < len(s) {
				i++
			}
			continue
		}
		b.WriteByte(s[i])
		i++
	}
	return b.String()
}
EOF
