		{"tty", ttyCaps()},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			var buf bytes.Buffer
			task := newTestProgress(t, &buf, tc.caps).Begin("fact backfill")
			task.Abandon()
			if out := strings.TrimSpace(stripANSI(buf.String())); out != "" {
