	t.Parallel()
	var buf bytes.Buffer
	task := newTestProgress(t, &buf, tui.PlainCaps()).Begin("fact backfill")
	task.Abandon()
	// A second terminal line for one task is exactly the duplicate the
	// finished flag exists to prevent; Abandon must share it.
	task.Finish(errors.New("boom"))
	if out := strings.TrimSpace(stripANSI(buf.String())); out != "" {
		t.Fatalf("Finish after Abandon must stay silent, got %q", out)
	}
}

func TestFinishStillWritesWhenTheTaskWasNotAbandoned(t *testing.T) {
	t.Parallel()
	// Non-vacuity for the two tests above: the identical setup DOES write when
