// Half a command is worse than none: it cannot be run, and it still looks
// like the line answered the question. Backticks are balanced, so an odd
// count before the cut means it lands inside one; back up to that span's
// opening backtick and drop it whole.
func truncateDoctorHead(runes []rune, budget int) string {
	cut := budget
	if cut > len(runes) {
		cut = len(runes)
	}
	if strings.Count(string(runes[:cut]), "`")%2 == 1 {
		for cut > 0 && runes[cut-1] != '`' {
