	// read "...; run\\u2026". Trim the dangling lead-in.
	for _, lead := range []string{"; run", " run", "; try", " try"} {
		kept = strings.TrimSuffix(kept, lead)
	}
	return strings.TrimRight(kept, " ,;")
}

