// live, without BEGINNING inside a `command` span -- a tail that opens
// mid-command shows an unrunnable fragment just as a head cut does.
func truncateDoctorTail(runes []rune, budget int) string {
	if budget <= 0 || budget >= len(runes) {
		return ""
