		// Opens inside a span: walk forward to just past its closing backtick.
		for start < len(runes) && runes[start] != '`' {
			start++
		}
		start++
	}
	if start >= len(runes) {
		return ""
	}
	return strings.TrimLeft(string(runes[start:]), " ,;")
