// TestEveryDeclaredToolIsReachable pins COR-2163's defect class: a tool can be
// declared and unroutable, or routed and undeclared, and nothing notices.
//
// brain_remember shipped in v0.1.0's binary with a dispatch case and no
// declaration, so no client could see it and the released brain could not
// record a memory for weeks. brain_recall had neither. Both failures are
// invisible to every other test, because declaration and dispatch are two
// lists nothing compares.
func TestEveryDeclaredToolIsReachable(t *testing.T) {
	t.Parallel()
	defs := mcpToolDefinitions()
	if len(defs) == 0 {
		t.Fatal("no tool definitions; the rest of this test would vacuously pass")
	}

	declared := make(map[string]bool, len(defs))
	for _, def := range defs {
		name, _ := def["name"].(string)
		if name == "" {
			t.Fatalf("a tool definition has no name: %v", def)
		}
		if declared[name] {
			t.Fatalf("tool %q is declared twice", name)
		}
		declared[name] = true
		if _, ok := def["inputSchema"]; !ok {
			t.Fatalf("tool %q has no inputSchema, so a client cannot call it correctly", name)
		}
	}

	// The two memory tools are the ones this regression actually cost us, so
	// name them rather than trusting the generic check to cover them.
	for _, required := range []string{"brain_remember", "brain_recall"} {
		if !declared[required] {
			t.Fatalf("%s is not declared; an agent on this surface cannot %s memory",
				required, map[string]string{"brain_remember": "write", "brain_recall": "read back"}[required])
		}
	}

	// Every declared name must route. An unroutable name reaches the
	// "unknown tool" arm, which is the exact shape of a declared-but-dead tool.
	for name := range declared {
		raw, err := json.Marshal(map[string]any{"name": name, "arguments": map[string]any{}})
		if err != nil {
			t.Fatalf("marshal params for %s: %v", name, err)
		}
		_, callErr := mcpHandleToolsCall(context.Background(), Options{}, json.RawMessage(raw))
		if callErr != nil && strings.Contains(callErr.Error(), "unknown tool") {
			t.Fatalf("tool %q is declared but does not route: %v", name, callErr)
		}
	}
}
EOF
