package webhook

import (
	"encoding/json"
	"errors"
	"log/slog"
	"net/http"

	"github.com/entireio/acme-payments/internal/charge"
	"github.com/entireio/acme-payments/internal/store"
)

// Event is a provider callback.
type Event struct {
	Type        string `json:"type"`
	ChargeID    string `json:"charge_id"`
	ProviderRef string `json:"provider_ref"`
}

// Handler verifies and applies provider callbacks.
type Handler struct {
	Verifier *Verifier
	Charges  *charge.Service
	Log      *slog.Logger
}

// ServeHTTP applies one provider event.
//
// THE ORDERING TRAP: the provider can deliver "charge.captured" BEFORE our own
// Create has committed. Their network hop is often faster than our write, so a
// handler that treats "charge not found" as a hard error drops real captures
// under load, and the money is taken while our side says pending forever.
//
// A 404 from the store is therefore answered with 409, not 500 and not 200:
// 409 tells the provider to retry with backoff, and by the next delivery the
// charge exists. 200 would make it stop retrying and lose the event; 500 gets
// the endpoint marked unhealthy and disabled.
func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	body, err := readLimited(r)
	if err != nil {
		http.Error(w, "payload too large", http.StatusRequestEntityTooLarge)
		return
	}
	if err := h.Verifier.Verify(r.Header.Get("Acme-Signature"), body); err != nil {
		http.Error(w, "bad signature", http.StatusUnauthorized)
		return
	}

	var ev Event
	if err := json.Unmarshal(body, &ev); err != nil {
		http.Error(w, "bad payload", http.StatusBadRequest)
		return
	}
	if ev.Type != "charge.captured" {
		w.WriteHeader(http.StatusNoContent)
		return
	}

	switch err := h.Charges.Capture(r.Context(), ev.ChargeID, ev.ProviderRef); {
	case err == nil:
		w.WriteHeader(http.StatusNoContent)
	case errors.Is(err, store.ErrNotFound):
		h.Log.Info("capture arrived before the charge was visible; asking for a retry",
			"charge_id", ev.ChargeID)
		http.Error(w, "charge not yet visible, retry", http.StatusConflict)
	default:
		http.Error(w, "internal error", http.StatusInternalServerError)
	}
}

const maxWebhookBytes = 1 << 20

func readLimited(r *http.Request) ([]byte, error) {
	defer r.Body.Close()
	limited := http.MaxBytesReader(nil, r.Body, maxWebhookBytes)
	buf := make([]byte, 0, 4096)
	tmp := make([]byte, 4096)
	for {
		n, err := limited.Read(tmp)
		buf = append(buf, tmp[:n]...)
		if err != nil {
			if err.Error() == "EOF" {
				return buf, nil
			}
			return nil, err
		}
	}
}
EOF

cat > internal/api/routes.go <<'EOF'
// Package api wires HTTP routes onto the payment services.
package api

import (
	"encoding/json"
	"errors"
	"log/slog"
	"net/http"

	"github.com/entireio/acme-payments/internal/charge"
	"github.com/entireio/acme-payments/internal/ledger"
	"github.com/entireio/acme-payments/internal/money"
	"github.com/entireio/acme-payments/internal/store"
	"github.com/entireio/acme-payments/internal/webhook"
)

// Server holds the dependencies every route needs.
type Server struct {
	Charges *charge.Service
	Journal *ledger.Journal
	Hook    *webhook.Handler
	Log     *slog.Logger
}

// Routes returns the mux for the service.
func (s *Server) Routes() *http.ServeMux {
	mux := http.NewServeMux()
	mux.HandleFunc("POST /v1/charges", s.createCharge)
	mux.HandleFunc("GET /v1/charges/{id}", s.getCharge)
	mux.HandleFunc("GET /v1/charges/{id}/ledger", s.getLedger)
	mux.Handle("POST /v1/webhooks/provider", s.Hook)
	mux.HandleFunc("GET /healthz", s.health)
	return mux
}

type createChargeRequest struct {
	AmountMinor int64  `json:"amount_minor"`
	Currency    string `json:"currency"`
	CustomerID  string `json:"customer_id"`
}

func (s *Server) createCharge(w http.ResponseWriter, r *http.Request) {
	var req createChargeRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad payload", http.StatusBadRequest)
		return
	}
	amt, err := money.New(req.AmountMinor, currencyFor(req.Currency))
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	rec, err := s.Charges.Create(r.Context(), charge.Request{
		IdempotencyKey: r.Header.Get("Idempotency-Key"),
		Amount:         amt,
		CustomerID:     req.CustomerID,
	})
	switch {
	case errors.Is(err, charge.ErrIdempotencyKeyRequired):
		// 400, not 422: the request is unprocessable before we look at the body.
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	case errors.Is(err, charge.ErrKeyReusedWithNewBody):
		http.Error(w, err.Error(), http.StatusConflict)
		return
	case err != nil:
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	writeJSON(w, http.StatusCreated, rec)
}

func (s *Server) getCharge(w http.ResponseWriter, r *http.Request) {
	rec, err := s.Charges.Store.GetCharge(r.Context(), r.PathValue("id"))
	if errors.Is(err, store.ErrNotFound) {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	writeJSON(w, http.StatusOK, rec)
}

func (s *Server) getLedger(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, s.Journal.Entries(r.Context(), r.PathValue("id")))
}

func (s *Server) health(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

func writeJSON(w http.ResponseWriter, code int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(v)
}

func currencyFor(code string) money.Currency {
	switch code {
	case "JPY":
		return money.JPY
	case "EUR":
		return money.EUR
	case "GBP":
		return money.GBP
	default:
		return money.USD
	}
}
EOF

cat > cmd/payments/main.go <<'EOF'
// Command payments runs the Acme Payments service.
package main

import (
	"log/slog"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/entireio/acme-payments/internal/api"
	"github.com/entireio/acme-payments/internal/charge"
	"github.com/entireio/acme-payments/internal/ledger"
	"github.com/entireio/acme-payments/internal/store"
	"github.com/entireio/acme-payments/internal/webhook"
)

func main() {
	log := slog.New(slog.NewJSONHandler(os.Stdout, nil))

	mem := store.NewMemory()
	journal := ledger.NewJournal()
	charges := &charge.Service{Store: mem, Journal: journal}

	srv := &api.Server{
		Charges: charges,
		Journal: journal,
		Log:     log,
		Hook: &webhook.Handler{
			Verifier: &webhook.Verifier{Secrets: secrets()},
			Charges:  charges,
			Log:      log,
		},
	}

	addr := os.Getenv("ADDR")
	if addr == "" {
		addr = ":8080"
	}
	log.Info("listening", "addr", addr)

	httpSrv := &http.Server{
		Addr:              addr,
		Handler:           srv.Routes(),
		ReadHeaderTimeout: 5 * time.Second,
	}
	if err := httpSrv.ListenAndServe(); err != nil {
		log.Error("server stopped", "err", err)
		os.Exit(1)
	}
}

// secrets reads the rotation set, newest first.
func secrets() []string {
	raw := os.Getenv("ACME_WEBHOOK_SECRETS")
	if raw == "" {
		return []string{"whsec_demo"}
	}
	return strings.Split(raw, ",")
}
