// Command payments runs the Acme Payments service.
package main

import (
	"log/slog"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/entireio/acme-payments/internal/api"
	"github.com/entireio/acme-payments/internal/charge"
	"github.com/entireio/acme-payments/internal/ledger"
	"github.com/entireio/acme-payments/internal/store"
	"github.com/entireio/acme-payments/internal/webhook"
)

func main() {
	log := slog.New(slog.NewJSONHandler(os.Stdout, nil))

	mem := store.NewMemory()
	journal := ledger.NewJournal()
	charges := &charge.Service{Store: mem, Journal: journal}

	srv := &api.Server{
		Charges: charges,
		Journal: journal,
		Log:     log,
		Hook: &webhook.Handler{
			Verifier: &webhook.Verifier{Secrets: secrets()},
			Charges:  charges,
			Log:      log,
		},
	}

	addr := os.Getenv("ADDR")
	if addr == "" {
		addr = ":8080"
	}
	log.Info("listening", "addr", addr)

	httpSrv := &http.Server{
		Addr:              addr,
		Handler:           srv.Routes(),
		ReadHeaderTimeout: 5 * time.Second,
	}
	if err := httpSrv.ListenAndServe(); err != nil {
		log.Error("server stopped", "err", err)
		os.Exit(1)
	}
}

// secrets reads the rotation set, newest first.
func secrets() []string {
	raw := os.Getenv("ACME_WEBHOOK_SECRETS")
	if raw == "" {
		return []string{"whsec_demo"}
	}
	return strings.Split(raw, ",")
}
