package charge

import (
	"context"
	"errors"
	"testing"
	"time"

	"github.com/entireio/acme-payments/internal/ledger"
	"github.com/entireio/acme-payments/internal/money"
	"github.com/entireio/acme-payments/internal/store"
)

func newService() *Service {
	return &Service{
		Store:   store.NewMemory(),
		Journal: ledger.NewJournal(),
		Now:     func() time.Time { return time.Unix(1700000000, 0).UTC() },
	}
}

func usd(t *testing.T, minor int64) money.Amount {
	t.Helper()
	a, err := money.New(minor, money.USD)
	if err != nil {
		t.Fatal(err)
	}
	return a
}

// A retry after a lost response must not bill the customer twice.
func TestReplayReturnsTheOriginalChargeAndDoesNotBillTwice(t *testing.T) {
	s := newService()
	ctx := context.Background()
	req := Request{IdempotencyKey: "key-1", Amount: usd(t, 2500), CustomerID: "cus_1"}

	first, err := s.Create(ctx, req)
	if err != nil {
		t.Fatal(err)
	}
	second, err := s.Create(ctx, req)
	if err != nil {
		t.Fatal(err)
	}
	if first.ID != second.ID {
		t.Fatalf("replay created a SECOND charge: %s then %s", first.ID, second.ID)
	}
}

func TestMissingIdempotencyKeyIsRefused(t *testing.T) {
	s := newService()
	_, err := s.Create(context.Background(), Request{Amount: usd(t, 100)})
	if !errors.Is(err, ErrIdempotencyKeyRequired) {
		t.Fatalf("want ErrIdempotencyKeyRequired, got %v", err)
	}
}

// The same key with a different amount is a client bug, not a new charge.
func TestReusedKeyWithDifferentAmountIsAnError(t *testing.T) {
	s := newService()
	ctx := context.Background()
	if _, err := s.Create(ctx, Request{IdempotencyKey: "k", Amount: usd(t, 100)}); err != nil {
		t.Fatal(err)
	}
	_, err := s.Create(ctx, Request{IdempotencyKey: "k", Amount: usd(t, 999)})
	if !errors.Is(err, ErrKeyReusedWithNewBody) {
		t.Fatalf("want ErrKeyReusedWithNewBody, got %v", err)
	}
}

// Providers retry webhooks. A second capture must not double the ledger.
func TestDuplicateCaptureDoesNotDoubleTheLedger(t *testing.T) {
	s := newService()
	ctx := context.Background()
	rec, err := s.Create(ctx, Request{IdempotencyKey: "k", Amount: usd(t, 5000)})
	if err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 3; i++ {
		if err := s.Capture(ctx, rec.ID, "pr_1"); err != nil {
			t.Fatal(err)
		}
	}
	net, err := s.Journal.NetCaptured(ctx, rec.ID, money.USD)
	if err != nil {
		t.Fatal(err)
	}
	if net.Minor != 0 {
		t.Fatalf("double-entry must net to zero across accounts, got %s", net)
	}
	if got := len(s.Journal.Entries(ctx, rec.ID)); got != 2 {
		t.Fatalf("three captures wrote %d entries; expected exactly one pair", got)
	}
}

// The capture callback can beat our own write. That must be retryable.
func TestCaptureBeforeChargeExistsIsNotFound(t *testing.T) {
	s := newService()
	err := s.Capture(context.Background(), "ch_never_written", "pr_1")
	if !errors.Is(err, store.ErrNotFound) {
		t.Fatalf("want store.ErrNotFound so the handler can answer 409, got %v", err)
	}
}
